/* BERTH.A RC234 — Biblioteca Kids embutida (sem dependência de paths externos) */
(function(){
'use strict';
const BUILD='RC234';
const KINDS=["head", "neck", "eyes", "back", "special"];
const LIB={"cat": {"pet": "Gato Neblina", "names": ["Boné de Bruma", "Coleira Lunar", "Óculos Neblina", "Mochila Etérea", "Amuleto de Bruma"]}, "rabbit": {"pet": "Coelho de Nuvem", "names": ["Boné de Nuvem", "Bandana de Bruma", "Óculos de Grau Nuvem", "Mochila Saltinho", "Pingente Coelho de Nuvem"]}, "fox": {"pet": "Raposa Neblina", "names": ["Gorro Aurora", "Lenço Estelar", "Óculos da Raposa", "Mochila Cauda Estelar", "Amuleto Raposa Celeste"]}, "owl": {"pet": "Corujinha Lunar", "names": ["Chapéu Pena Lunar", "Gravata Lua-Sábia", "Óculos de Leitura Lunar", "Bolsa-Livro Celeste", "Medalhão Pena Oráculo"]}, "deer": {"pet": "Cervo de Nuvem", "names": ["Tiara Nuvem Lunar", "Coleira Celeste", "Monóculo Encantado", "Mochila Cervo de Nuvem", "Varinha Mágica Celeste"]}, "bear": {"pet": "Ursinho de Bruma", "names": ["Gorro Soninho de Bruma", "Lenço de Bruma", "Óculos Redondos de Bruma", "Mochilinha de Bruma", "Pingente Sonho de Bruma"]}};
const EMBED={"cat":{"head":"data:image/png;base64,","neck":"data:image/png;base64,","eyes":"data:image/png;base64,","back":"data:image/png;base64,","special":"data:image/png;base64,"},"rabbit":{"head":"data:image/png;base64,","neck":"data:image/png;base64,","eyes":"data:image/png;base64,","back":"data:image/png;base64,","special":"data:image/png;base64,"},"fox":{"head":"data:image/png;base64,","neck":"data:image/png;base64,","eyes":"data:image/png;base64,","back":"data:image/png;base64,","special":"data:image/png;base64,"},"owl":{"head":"data:image/png;base64,","neck":"data:image/png;base64,","eyes":"data:image/png;base64,","back":"data:image/png;base64,","special":"data:image/png;base64,"},"deer":{"head":"data:image/png;base64,","neck":"data:image/png;base64,","eyes":"data:image/png;base64,","back":"data:image/png;base64,","special":"data:image/png;base64,"},"bear":{"head":"data:image/png;base64,","neck":"data:image/png;base64,","eyes":"data:image/png;base64,","back":"data:image/png;base64,","special":"data:image/png;base64,"}};
function exactTextElements(text){return [...document.querySelectorAll('h1,h2,h3,h4,strong')].filter(el=>(el.textContent||'').trim()===text);}
function findLibraryCard(pet){
 for(const heading of exactTextElements(pet)){
  let n=heading;
  for(let i=0;i<9&&n;i++,n=n.parentElement){
   const t=(n.textContent||'');
   if(t.includes('BIBLIOTECA DO COMPANHEIRO') && t.includes(pet)) return n;
  }
 }
 return null;
}
function renderLibrary(animal,cfg){
 const card=findLibraryCard(cfg.pet); if(!card)return;
 if(card.dataset.rc234Library===animal)return;
 card.dataset.rc234Library=animal;
 card.classList.add('rc233-library-card','rc234-library-card');
 const items=KINDS.map((kind,i)=>`<div class="rc233-library-item"><div class="rc233-library-art"><img src="${EMBED[animal][kind]}" alt="" loading="eager" decoding="sync"></div><div class="rc233-library-name">${cfg.names[i]}</div></div>`).join('');
 card.innerHTML=`<div class="rc233-library-head"><div class="rc233-library-kicker">BIBLIOTECA DO COMPANHEIRO</div><h3>${cfg.pet}</h3><p>Os cinco acessórios são próprios deste pet. As imagens e nomes abaixo acompanham o pack atual homologado.</p></div><div class="rc233-library-grid">${items}</div>`;
}
function patchLibraries(){Object.entries(LIB).forEach(([a,c])=>renderLibrary(a,c));}
function stamp(){
 document.documentElement.dataset.berthaBuild=BUILD; document.documentElement.dataset.berthaIndex=BUILD; document.title='BERTH.A · Homologação '+BUILD;
 const idx=document.getElementById('rc157IndexBadge'); if(idx)idx.textContent='INDEX · '+BUILD;
 document.querySelectorAll('body *').forEach(el=>{if(el.children.length)return;const t=(el.textContent||'').trim();if(/^HML\s*·\s*RC\d+/i.test(t))el.textContent='HML · '+BUILD;});
}
function patch(){patchLibraries();stamp();}
const style=document.createElement('style');style.id='rc234-library-embedded-style';style.textContent=`
.rc234-library-card .rc233-library-art img{display:block!important;width:88px!important;height:88px!important;object-fit:contain!important;object-position:center!important}
@media(max-width:430px){.rc234-library-card .rc233-library-art img{width:80px!important;height:80px!important}}
`;document.head.appendChild(style);
let raf=0;function schedule(){if(raf)return;raf=requestAnimationFrame(()=>{raf=0;patch();});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
window.addEventListener('pageshow',schedule);window.addEventListener('hashchange',()=>setTimeout(schedule,40));
document.addEventListener('click',e=>{if(e.target.closest('[data-r147tab="kids"],[data-r152pet],#rc208PetSel,#r152KidSel'))setTimeout(schedule,70);},true);
document.addEventListener('change',e=>{if(e.target.matches('#rc208PetSel,#r152KidSel'))setTimeout(schedule,70);},true);
[120,350,800,1600,2600].forEach(ms=>setTimeout(schedule,ms));
})();
